import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        int MOD = 1000000007;
        int[] adj = new int[n + 1];
        boolean[] visited = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            adj[i] = (i * k) % n;
        }

        int groups = 0;

        for (int start = 1; start < n; start++) {
            if (!visited[start]) {
                walk(start, adj, visited);
                groups++;
            }
        }

        if (k == 1) {
            System.out.println(pow(n, n, MOD));
        } else {
            System.out.println(pow(n, groups, MOD));
        }
    }

    private static void walk(int node, int[] adj, boolean[] visited) {
        visited[node] = true;
        while (!visited[adj[node]]) {
            node = adj[node];
            visited[node] = true;
        }
    }

    private static long pow(long base, int exp, int mod) {
        long result = 1;
        long b = base % mod;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }
}
